    var sep = url.indexOf('?') >= 0 ? '&' : '?';
    return url + sep + 'cmsTemplate=1&languageId=' + languageId + '&_=' + new Date().getTime();
}

function fetchWithTimeout(url, options, timeoutMs) {
    var waitMs = timeoutMs || fetchTimeoutMs;
    return new Promise(function (resolve, reject) {
        var timer = window.setTimeout(function () {
            reject(new Error('Timeout sau ' + Math.round(waitMs / 1000) + ' giây'));
        }, waitMs);
        fetch(url, options || {}).then(function (response) {
            window.clearTimeout(timer);
            resolve(response);
        }).catch(function (error) {
            window.clearTimeout(timer);
            reject(error);
        });
    });
}

function readFrontend(url, languageId) {
    return fetchWithTimeout(appendQuery(url, languageId), { method: 'GET', credentials: 'omit', mode: 'cors', cache: 'no-store' }, fetchTimeoutMs)
        .then(function (response) {
            if (!response.ok) throw new Error('HTTP ' + response.status);
            return response.text();
        })
        .then(function (text) {
            var doc = new DOMParser().parseFromString(text, 'text/html');
            var root = doc.querySelector('.about-page');
            if (!root) throw new Error('Không tìm thấy .about-page trong frontend.');
            var style = doc.querySelector('#about-page-base-style');
            return { html: root.outerHTML, baseCss: style ? style.textContent : '' };
        });
}

function loadStaticBaseCss() {
    if (!baseCssUrl) return Promise.resolve(false);
    return fetchWithTimeout(baseCssUrl, { method: 'GET', credentials: 'same-origin', cache: 'no-store' }, fetchTimeoutMs)
        .then(function (response) {
            if (!response.ok) throw new Error('HTTP ' + response.status);
            return response.text();
        })
        .then(function (text) {
            if (text) {
                baseCss = text;
                injectBaseCss();
            }
            return !!text;
        });
}

