private static void HandleImport(HttpContext context)
{
    SessionUser user = RequireLogin(context);
    if (user == null) return;

    string sourceUrl = (context.Request["url"] ?? string.Empty).Trim();
    int languageId = 1;
    int parsedLanguageId;
    if (int.TryParse(context.Request["languageId"], out parsedLanguageId)
        && (parsedLanguageId == 1 || parsedLanguageId == 2))
    {
        languageId = parsedLanguageId;
    }

    if (sourceUrl.Length == 0)
    {
        WriteJson(context, false, "URL frontend không hợp lệ.", null);
        return;
    }

    try
    {
        Uri fetchUri = ResolveFrontendUri(sourceUrl);
        string fetchUrl = AppendCmsTemplateQuery(fetchUri.AbsoluteUri, languageId);
        string html = DownloadFrontendHtml(fetchUrl);
        string pageHtml = ExtractAboutRootHtml(html);
        pageHtml = SanitizeHtml(pageHtml);
        string baseCss = ExtractAboutBaseCss(html);
        if (string.IsNullOrWhiteSpace(baseCss))
            baseCss = LoadBundledBaseCss(context);

        if (string.IsNullOrWhiteSpace(pageHtml))
        {
            WriteJson(context, false, "Không tìm thấy .about-page trong frontend.", null);
            return;
        }

        Dictionary<string, object> data = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase);
        data["Html"] = pageHtml;
        data["BaseCss"] = baseCss ?? string.Empty;
        WriteJson(context, true, "OK", data);
    }
    catch (Exception ex)
    {
        System.Diagnostics.Debug.WriteLine("AboutPageHandler import: " + ex);
        WriteJson(context, false, "Không nạp được frontend: " + ex.Message, null);
    }
}

private static string LoadBundledBaseCss(HttpContext context)
{
