private static Uri ResolveFrontendUri(string sourceUrl)
{
    Uri uri;
    if (!Uri.TryCreate(sourceUrl, UriKind.Absolute, out uri))
    {
        string root = CMSGlobal.WebsiteRoot;
        if (string.IsNullOrWhiteSpace(root))
            throw new InvalidOperationException("Chưa cấu hình WebsiteRoot trong Web.config.");

        string combined = root.Trim().TrimEnd('/') + "/" + sourceUrl.Trim().TrimStart('/');
        if (!Uri.TryCreate(combined, UriKind.Absolute, out uri))
            throw new InvalidOperationException("URL frontend không hợp lệ.");
    }

    ValidateFrontendUri(uri);
    return uri;
}

private static void ValidateFrontendUri(Uri uri)
{
    if (uri == null) return;

    if (IsLoopbackHost(uri.Host))
        return;

    Uri allowedRoot;
    if (!Uri.TryCreate(CMSGlobal.WebsiteRoot, UriKind.Absolute, out allowedRoot))
        return;

    if (!string.Equals(uri.Host, allowedRoot.Host, StringComparison.OrdinalIgnoreCase))
        throw new InvalidOperationException("Chỉ được nạp frontend cùng domain WebsiteRoot hoặc localhost dev.");
}

private static bool IsLoopbackHost(string host)
{
    if (string.IsNullOrWhiteSpace(host)) return false;

    string value = host.Trim().ToLowerInvariant();
    return value == "localhost"
        || value == "127.0.0.1"
        || value == "::1"
        || value == "[::1]";
}

private static string AppendCmsTemplateQuery(string url, int languageId)
{
    string separator = url.IndexOf('?') >= 0 ? "&" : "?";
    return url + separator + "cmsTemplate=1&languageId=" + languageId.ToString();
}

private static string DownloadFrontendHtml(string url)
{
    try
    {
        using (WebClient client = new WebClient())
        {
            client.Encoding = Encoding.UTF8;
            client.Headers.Add("User-Agent", "AboutCMS/1.0");
            return client.DownloadString(url);
        }
    }
    catch (WebException ex)
    {
        string detail = ex.Message;
        HttpWebResponse httpResponse = ex.Response as HttpWebResponse;
        if (httpResponse != null)
            detail = string.Format("HTTP {0}", (int)httpResponse.StatusCode);

        throw new InvalidOperationException(
            string.Format("CMS không truy cập được HOS ({0}): {1}", url, detail), ex);
    }
}

private static string ExtractAboutBaseCss(string html)
{
    if (string.IsNullOrEmpty(html)) return string.Empty;

    Match match = Regex.Match(
        html,
        @"<style\b[^>]*\bid\s*=\s*(?:""about-page-base-style""|'about-page-base-style')[^>]*>([\s\S]*?)</style>",
        RegexOptions.IgnoreCase);
    if (!match.Success) return string.Empty;
    return match.Groups[1].Value;
}

private static string ExtractAboutRootHtml(string html)
{
    if (string.IsNullOrEmpty(html)) return string.Empty;

    int marker = html.IndexOf("about-page", StringComparison.OrdinalIgnoreCase);
    if (marker < 0) return string.Empty;

    int divStart = html.LastIndexOf("<div", marker, StringComparison.OrdinalIgnoreCase);
    if (divStart < 0) return string.Empty;

    return ExtractBalancedDiv(html, divStart);
}

private static string ExtractBalancedDiv(string html, int startIndex)
{
    int depth = 0;
    int index = startIndex;

    while (index < html.Length)
    {
        int tagStart = html.IndexOf('<', index);
        if (tagStart < 0) break;

        if (tagStart + 4 <= html.Length
            && string.Compare(html, tagStart, "<div", 0, 4, StringComparison.OrdinalIgnoreCase) == 0)
        {
            depth++;
        }
        else if (tagStart + 6 <= html.Length
            && string.Compare(html, tagStart, "</div", 0, 5, StringComparison.OrdinalIgnoreCase) == 0)
        {
            depth--;
            int tagEnd = html.IndexOf('>', tagStart);
            if (tagEnd < 0) break;
            if (depth == 0)
                return html.Substring(startIndex, tagEnd - startIndex + 1);
            index = tagEnd + 1;
            continue;
        }

        index = tagStart + 1;
    }

    return string.Empty;
}

