function stripFontImportsFromCss(cssText) {
    if (!cssText) return '';
    return String(cssText).replace(/@import\s+url\([^)]*fonts\.googleapis\.com[^)]*\)\s*;?/gi, '');
}

function ensureCanvasFonts(doc) {
    if (!doc || !doc.head) return;
    var link = doc.getElementById('about-cms-fonts');
    if (!link) {
        link = doc.createElement('link');
        link.id = 'about-cms-fonts';
        link.rel = 'stylesheet';
        link.href = aboutFontCssUrl;
        doc.head.appendChild(link);
    } else if (link.href !== aboutFontCssUrl) {
        link.href = aboutFontCssUrl;
    }
}

